package docker

import (
	"os/exec"
	"strings"
)

// ContainerLaunchOptions holds parameters for running a container
type ContainerLaunchOptions struct {
	Name        string   // container name (optional)
	Image       string   // image to run
	Entrypoint  string   // override default entrypoint (optional)
	Ports       []string // "hostPort:containerPort"
	Env         []string // "KEY=VALUE"
	Volumes     []string // "name:/path"
	Network     string   // network name
	User        string   // user to run as (--user UID:GID or username, optional)
	Detach      bool     // run in background (-d)
	Remove      bool     // automatically remove the container when it exits (--rm)
	Interactive bool     // keep STDIN open even if not attached (-i)
	TTY         bool     // allocate a pseudo-TTY (-t)
}

// buildLaunchArgs constructs the docker run argument list for the given options.
func buildLaunchArgs(opts ContainerLaunchOptions) []string {
	args := []string{"run"}
	if opts.Remove {
		args = append(args, "--rm")
	}
	if opts.Detach {
		args = append(args, "-d")
	}
	if opts.Interactive {
		args = append(args, "-i")
	}
	if opts.TTY {
		args = append(args, "-t")
	}
	if opts.Name != "" {
		args = append(args, "--name", opts.Name)
	}
	if opts.Entrypoint != "" {
		args = append(args, "--entrypoint", opts.Entrypoint)
	}
	for _, p := range opts.Ports {
		if p != "" {
			args = append(args, "-p", p)
		}
	}
	for _, e := range opts.Env {
		if e != "" {
			args = append(args, "-e", e)
		}
	}
	for _, v := range opts.Volumes {
		if v != "" {
			args = append(args, "-v", v)
		}
	}
	if opts.Network != "" {
		args = append(args, "--network", opts.Network)
	}
	if opts.User != "" {
		args = append(args, "--user", opts.User)
	}
	args = append(args, opts.Image)
	return args
}

// BuildLaunchCmd returns a ready-to-run exec.Cmd for the given options without executing it.
// Use this when you need to hand off the process to a terminal (e.g. tea.ExecProcess for -it mode).
func BuildLaunchCmd(opts ContainerLaunchOptions) (*exec.Cmd, error) {
	if err := requireDocker(); err != nil {
		return nil, err
	}
	return runner.Build(buildLaunchArgs(opts)...), nil
}

// LaunchContainer runs a new container with the given options and returns its ID/output.
// Do NOT use this for interactive (-it) containers — use BuildLaunchCmd + tea.ExecProcess instead.
func LaunchContainer(opts ContainerLaunchOptions) (string, error) {
	if err := requireDocker(); err != nil {
		return "", err
	}
	output, err := dockerCombined(buildLaunchArgs(opts)...)
	if err != nil {
		return "", errWithOutput("docker run", output)
	}
	return strings.TrimSpace(string(output)), nil
}

// VerifyEntrypoint checks if the given binary is available inside an image
// by running a short-lived throwaway container with /bin/sh -c "command -v <binary>".
// Returns true if the binary is found, false otherwise.
func VerifyEntrypoint(image, entrypoint string) (bool, error) {
	if err := requireDocker(); err != nil {
		return false, err
	}
	_, err := dockerCombined("run", "--rm", "--entrypoint", "/bin/sh",
		image, "-c", "command -v "+entrypoint)
	return err == nil, nil
}

package docker

import (
	"strconv"
	"strings"
)

// OCIStats contains OCI resource counts and disk usage
type OCIStats struct {
	Available       bool
	ImagesCount     int
	ImagesSize      string
	ContainersCount int
	ContainersSize  string
	VolumesCount    int
	VolumesSize     string

	// NetworksCount does **not** come from `docker system df`, which has no row
	// for networks: they hold no bytes, so the disk report ignores them. It is
	// counted by a separate `docker network ls`, and it is the only figure in
	// this struct that costs a second call.
	NetworksCount int

	// BuildCacheSize is the fourth row `docker system df` prints, and the one
	// that answers "where did the disk go" most often — a build cache commonly
	// reaches tens of gigabytes. It was already part of the reclaimable sum;
	// only its own size used to be discarded.
	BuildCacheSize string

	// Reclaimable is what `docker system df` already reports and this package
	// used to drop on the floor: the space a prune would free, summed across
	// the three families. Docker gives it as "12.3GB (45%)" — only the size
	// is kept, the percentage is relative to its own family and would make no
	// sense once added up.
	Reclaimable string
}

// FetchOCIStats returns OCI resource counts and disk usage via docker system df
func FetchOCIStats() OCIStats {
	stats := OCIStats{}

	if runner.LookPath() != nil {
		return stats
	}

	output, err := dockerOutput("system", "df", "--format",
		"{{.Type}}\t{{.TotalCount}}\t{{.Size}}\t{{.Reclaimable}}")
	if err != nil {
		return stats
	}

	stats.Available = true
	var reclaimable int64

	for _, line := range splitLines(output) {
		parts := strings.SplitN(line, "\t", 4)
		if len(parts) < 3 {
			continue
		}
		count, _ := strconv.Atoi(parts[1])
		size := parts[2]
		if len(parts) >= 4 {
			// "12.3GB (45%)" — the percentage is relative to its own family
			// and would not survive an addition.
			reclaimable += parseSize(strings.TrimSpace(strings.Split(parts[3], "(")[0]))
		}

		switch parts[0] {
		case "Images":
			stats.ImagesCount = count
			stats.ImagesSize = size
		case "Containers":
			stats.ContainersCount = count
			stats.ContainersSize = size
		case "Local Volumes":
			stats.VolumesCount = count
			stats.VolumesSize = size
		case "Build Cache":
			stats.BuildCacheSize = size
		}
	}

	if reclaimable > 0 {
		stats.Reclaimable = formatSize(reclaimable)
	}

	// A list that fails leaves the count at zero rather than failing the
	// whole call: the sizes were just read and are worth returning.
	if networks, err := ListNetworks(); err == nil {
		stats.NetworksCount = len(networks)
	}

	return stats
}

