11	// dockerHubKeys lists all keys Docker uses for Docker Hub in ~/.docker/config.json.
12	// `docker login docker.io` stores credentials under "https://index.docker.io/v1/".
13	var dockerHubKeys = []string{
14		"docker.io",
15		"registry-1.docker.io",
16		"https://index.docker.io/v1/",
17		"https://index.docker.io/v1",
18		"https://registry-1.docker.io",
19	}
20	
21	// registryCandidates returns all URL variants to look up in ~/.docker/config.json.
22	func registryCandidates(registryURL string) []string {
23		base := strings.TrimSuffix(registryURL, "/")
24	
25		// Check if this URL is any known Docker Hub alias; if so, return the full set.
26		for _, alias := range dockerHubKeys {
27			if strings.EqualFold(base, strings.TrimSuffix(alias, "/")) {
28				return dockerHubKeys
29			}
30		}
31	
32		// Generic: bare hostname, https://, http:// variants.
33		candidates := []string{base}
34		if strings.HasPrefix(base, "https://") {
