1	package docker
2	
3	import (
4		"fmt"
5		"log"
6		"strconv"
7		"strings"
8	)
9	
10	// Container represents a Docker container with its metrics
11	type Container struct {
12		ID        string
13		Name      string
14		Image     string
15		State     string // running, exited, paused, created, restarting, dead
16		Status    string // "Up 2 hours", "Exited (0) 5min ago"
17		CreatedAt string // "2 hours ago"
18		// Ports is parsed here rather than carried as the string docker printed:
19		// the view must not learn to read Docker's output, and an opaque string
20		// cannot be searched by port number. See ParseContainerPorts.
21		Ports      []PortBinding
22		CPUPercent float64
23		MemUsage   string // "150MiB / 8GiB"
24		// MemBytes is the used half of MemUsage. It exists because MemPercent
25		// cannot be aggregated: it is a share of *this* container's limit, so two
26		// of them are fractions of different wholes (see Aggregate).
27		MemBytes   int64
28		MemPercent float64
29		NetIO      string // "1.2kB / 3.4kB"
30		NetRX      int64  // received bytes (parsed from NetIO)
31		NetTX      int64  // transmitted bytes (parsed from NetIO)
32		BlockIO    string // "1.2MB / 3.4MB"
33		BlockRX    int64  // block bytes read (parsed from BlockIO)
34		BlockTX    int64  // block bytes written (parsed from BlockIO)
35	}
36	
37	// ListContainers returns a list of containers. If all is true, includes stopped containers.
38	func ListContainers(all bool) ([]Container, error) {
39		if err := requireDocker(); err != nil {
40			return nil, err
41		}
42	
43		args := []string{"ps"}
44		if all {
45			args = append(args, "--all")
46		}
47		args = append(args, "--format", "{{.ID}}\t{{.Names}}\t{{.Image}}\t{{.State}}\t{{.Status}}\t{{.CreatedAt}}\t{{.Ports}}")
48	
49		output, err := dockerOutput(args...)
50		if err != nil {
51			return nil, wrapErr("docker ps", err)
52		}
53	
54		var containers []Container
55		for _, line := range splitLines(output) {
56			parts := strings.SplitN(line, "\t", 7)
57			if len(parts) < 4 {
58				continue
59			}
60			c := Container{
61				ID:    parts[0],
62				Name:  parts[1],
63				Image: parts[2],
64				State: parts[3],
65			}
66			if len(parts) > 4 {
67				c.Status = parts[4]
68			}
69			if len(parts) > 5 {
70				c.CreatedAt = parts[5]
71			}
72			if len(parts) > 6 {
73				c.Ports = ParseContainerPorts(parts[6])
74			}
75			containers = append(containers, c)
76		}
77	
78		return containers, nil
79	}
80	
81	// GetContainerMetrics returns CPU/Memory/Net metrics for running containers
82	func GetContainerMetrics() (map[string]Container, error) {
83		if err := requireDocker(); err != nil {
84			return nil, err
85		}
86	
87		output, err := dockerOutput("stats", "--no-stream", "--format",
88			"{{.ID}}\t{{.CPUPerc}}\t{{.MemUsage}}\t{{.MemPerc}}\t{{.NetIO}}\t{{.BlockIO}}")
89		if err != nil {
90			return nil, wrapErr("docker stats", err)
91		}
92	
93		metrics := make(map[string]Container)
94		for _, line := range splitLines(output) {
95			parts := strings.SplitN(line, "\t", 6)
96			if len(parts) < 5 {
97				continue
98			}
99	
100			cpu, _ := strconv.ParseFloat(strings.TrimSuffix(parts[1], "%"), 64)
101			mem, _ := strconv.ParseFloat(strings.TrimSuffix(parts[3], "%"), 64)
102			memBytes, _ := parsePair(parts[2])
103			netRX, netTX := parseNetIO(parts[4])
104	
105			var blockIO string
106			var blockRX, blockTX int64
107			if len(parts) >= 6 {
108				blockIO = parts[5]
109				blockRX, blockTX = parseNetIO(blockIO)
110			}
111			metrics[parts[0]] = Container{
112				ID:         parts[0],
113				CPUPercent: cpu,
114				MemUsage:   parts[2],
115				MemBytes:   memBytes,
116				MemPercent: mem,
117				NetIO:      parts[4],
118				NetRX:      netRX,
119				NetTX:      netTX,
120				BlockIO:    blockIO,
121				BlockRX:    blockRX,
122				BlockTX:    blockTX,
123			}
124		}
125	
126		return metrics, nil
127	}
128	
129	// Aggregate is what every running container adds up to, **on the daemon's
130	// scale**: both percentages run from 0 to 100, whatever the machine.
131	//
132	// That normalization is the whole of this type, and it exists because neither
133	// figure `docker stats` prints is one to begin with.
134	//
135	//   - `.CPUPerc` is relative to **one core**: Docker computes
136	//     `(cpuDelta/systemDelta) × onlineCPUs × 100`, so a container busy on two
137	//     cores reports 199% (measured, not assumed). Summed over the containers,
138	//     the raw total runs to `NCPU × 100` — 1400% on a sixteen-CPU daemon, which
139	//     is a true statement about fourteen cores and not a percentage of
140	//     anything. Divided by NCPU it becomes one.
141	//   - `.MemPerc` is relative to **that container's own limit**. Summing them
142	//     adds fractions of different wholes: a container capped at 256 MiB sitting
143	//     at 0.13% and one against the daemon's 15 GiB at 0.03% do not add up to
144	//     0.16% of anything. So the bytes are summed instead, over the daemon's own
145	//     total.
146	//
147	// It is measured *inside* the Docker VM on Windows and macOS, so it is still
148	// not addable with the host's numbers — it is a subset, and both dashboard
149	// sections say so in their title. What changes here is that the two are now at
150	// least in the same unit.
151	type Aggregate struct {
152		Available  bool
153		Running    int
154		CPUPercent float64
155		MemPercent float64
156	
157		// Cores is the daemon's CPU count, which is what CPUPercent was divided by.
158		// The dashboard prints it beside the figure for the same reason the host
159		// section prints its own: 40% of four cores and 40% of thirty-two do not
160		// describe the same machine.
161		Cores int
162	}
163	
164	// Capacity is what the daemon has to give, and therefore the denominator every
165	// percentage above is taken against.
166	type Capacity struct {
167		// Cores is `docker info`'s NCPU and MemTotal its memory, both as the
168		// *daemon* sees them — which on Windows and macOS is the VM's allocation
169		// and not the machine's. Reading the host's core count instead would be
170		// wrong on exactly the two platforms where Docker is not the host.
171		Cores    int
172		MemTotal int64
173	}
174	
175	// OK reports whether the capacity can serve as a denominator.
176	func (c Capacity) OK() bool { return c.Cores > 0 && c.MemTotal > 0 }
177	
178	// FetchCapacity reads what the daemon has, from `docker info`.
179	//
180	// It is read on every aggregate rather than memoized, and the 240 ms it costs
181	// (measured, against the 1–2 s `docker stats` already spends) is what buys it:
182	// a Docker Desktop reconfigured with a new CPU allocation changes this number
183	// under a running DevDesk, and a memo would divide by the old one for the life
184	// of the process — silently, since a wrong denominator still produces a
185	// plausible percentage.
186	func FetchCapacity() (Capacity, error) {
187		if err := requireDocker(); err != nil {
188			return Capacity{}, err
189		}
190		output, err := dockerOutput("info", "--format", "{{.NCPU}}\t{{.MemTotal}}")
191		if err != nil {
192			return Capacity{}, wrapErr("docker info", err)
193		}
194	
195		fields := strings.SplitN(strings.TrimSpace(string(output)), "\t", 2)
196		if len(fields) < 2 {
197			return Capacity{}, fmt.Errorf("docker info: unreadable capacity %q", output)
198		}
199		cores, err := strconv.Atoi(strings.TrimSpace(fields[0]))
200		if err != nil {
201			return Capacity{}, fmt.Errorf("docker info: unreadable NCPU %q: %w", fields[0], err)
202		}
203		total, err := strconv.ParseInt(strings.TrimSpace(fields[1]), 10, 64)
204		if err != nil {
