1	package docker
2	
3	import (
4		"context"
5		"strconv"
6		"strings"
7	)
8	
9	// Image represents a Docker image with its metadata
10	type Image struct {
11		ID         string
12		Repository string
13		Tag        string
14		Size       int64 // Content size (virtual size) in bytes
15		UniqueSize int64 // Disk usage (unique layers) in bytes
16		Containers int
17		CreatedAt  string
18	}
19	
20	// Name returns "repository:tag", omitting the tag suffix when tag is "<none>".
21	func (img Image) Name() string {
22		if img.Tag == "" || img.Tag == "<none>" {
23			return img.Repository
24		}
25		return img.Repository + ":" + img.Tag
26	}
27	
28	// ScanTarget returns the best identifier to pass to Trivy for a local scan.
29	// When an image has no tag, the short ID is used so Trivy resolves it locally
30	// instead of trying to pull "repository:latest" from a registry.
31	func (img Image) ScanTarget() string {
32		if img.Tag == "" || img.Tag == "<none>" {
33			return img.ID
34		}
35		return img.Name()
36	}
37	
38	// ListImages returns a list of local Docker images
39	func ListImages() ([]Image, error) {
40		if err := requireDocker(); err != nil {
41			return nil, err
42		}
43	
44		// {{.Size}} from docker image ls gives disk usage (not content size)
45		output, err := dockerOutput("image", "ls", "--format",
46			"{{.ID}}\t{{.Repository}}\t{{.Tag}}\t{{.Size}}\t{{.CreatedAt}}")
47		if err != nil {
48			return nil, wrapErr("docker image ls", err)
49		}
50	
51		var images []Image
52		for _, line := range splitLines(output) {
53			parts := strings.SplitN(line, "\t", 5)
54			if len(parts) < 3 {
55				continue
56			}
57			img := Image{
58				ID:         parts[0],
59				Repository: parts[1],
60				Tag:        parts[2],
61			}
62			if len(parts) > 3 {
63				// docker image ls {{.Size}} = disk usage
64				img.UniqueSize = parseSize(parts[3])
65			}
66			if len(parts) > 4 {
67				img.CreatedAt = parts[4]
68			}
69			images = append(images, img)
70		}
71	
72		// Enrich with content size from docker image inspect and
73		// more precise disk usage from docker system df -v
74		enrichImagesWithDiskUsage(images)
75		enrichImagesWithContentSize(images)
76	
77		return images, nil
78	}
79	
80	// enrichImagesWithContentSize populates Size (content size) from docker image inspect.
81	// docker image inspect .Size gives the real content size (compressed layers in content store),
82	// while docker image ls .Size gives disk usage (unpacked layers on disk).
83	func enrichImagesWithContentSize(images []Image) {
84		if len(images) == 0 {
85			return
86		}
87	
88		ids := make([]string, 0, len(images))
89		for _, img := range images {
90			ids = append(ids, img.ID)
91		}
92	
93		args := append([]string{"image", "inspect", "--format", "{{.ID}}\t{{.Size}}"}, ids...)
94		output, err := dockerOutput(args...)
95		if err != nil {
96			return
97		}
98	
99		// Build lookup by short ID (strip "sha256:" prefix, keep first 12 chars)
100		lookup := make(map[string]int64)
101		for _, line := range splitLines(output) {
102			parts := strings.SplitN(line, "\t", 2)
103			if len(parts) < 2 {
104				continue
105			}
106			shortID := strings.TrimPrefix(parts[0], "sha256:")
107			if len(shortID) > 12 {
108				shortID = shortID[:12]
109			}
110			size, _ := strconv.ParseInt(parts[1], 10, 64)
111			lookup[shortID] = size
112		}
113	
114		for i := range images {
115			if size, ok := lookup[images[i].ID]; ok {
116				images[i].Size = size
117			}
118		}
119	}
120	
121	// dfInfo holds the per-image figures scraped from `docker system df -v`.
122	type dfInfo struct {
123		UniqueSize int64
124		Containers int
125	}
126	
127	// enrichImagesWithDiskUsage populates UniqueSize and Containers from docker system df -v.
128	// Parses the raw text output because --format with -v does not expose per-image fields.
129	func enrichImagesWithDiskUsage(images []Image) {
130		output, err := dockerOutput("system", "df", "-v")
131		if err != nil {
132			return
133		}
134	
135		lookup := parseImagesDiskUsage(string(output))
136		for i := range images {
137			key := images[i].Repository + ":" + images[i].Tag
138			if info, ok := lookup[key]; ok {
139				images[i].UniqueSize = info.UniqueSize
140				images[i].Containers = info.Containers
141			}
142		}
143	}
144	
145	// parseImagesDiskUsage extracts the "Images space usage" table from
146	// `docker system df -v`, keyed by "repository:tag".
147	//
148	// The table is fixed-width rather than delimited, so column offsets are taken
149	// from the header line and every row is sliced at those offsets.
150	func parseImagesDiskUsage(output string) map[string]dfInfo {
151		lookup := make(map[string]dfInfo)
152	
153		inImages := false
154		headerFound := false
155		var tagPos, uniquePos, contPos int
156	
157		for _, line := range strings.Split(output, "\n") {
158			trimmed := strings.TrimSpace(line)
159	
160			if strings.HasPrefix(trimmed, "Images space usage:") {
161				inImages = true
162				continue
163			}
164			if inImages && (strings.HasPrefix(trimmed, "Containers space usage:") ||
165				strings.HasPrefix(trimmed, "Local Volumes space usage:") ||
166				strings.HasPrefix(trimmed, "Build cache usage:")) {
167				break
168			}
169			if !inImages || trimmed == "" {
170				continue
171			}
172	
173			if strings.HasPrefix(trimmed, "REPOSITORY") {
174				tagPos = strings.Index(line, "TAG")
175				uniquePos = strings.Index(line, "UNIQUE SIZE")
176				contPos = strings.Index(line, "CONTAINERS")
177				headerFound = tagPos > 0 && uniquePos > 0 && contPos > 0
178				continue
179			}
180			if !headerFound {
181				continue
182			}
183	
184			repo := strings.TrimSpace(safeSlice(line, 0, tagPos))
185			// The TAG column is short; take the first word so it cannot bleed into IMAGE ID.
186			tag := firstWord(strings.TrimSpace(safeSlice(line, tagPos, tagPos+tagColumnWidth)))
187			uniqueStr := strings.TrimSpace(safeSlice(line, uniquePos, contPos))
188			contStr := firstWord(strings.TrimSpace(safeSlice(line, contPos, len(line))))
189	
190			if repo == "" || tag == "" {
191				continue
192			}
193			containers, _ := strconv.Atoi(contStr)
194			lookup[repo+":"+tag] = dfInfo{UniqueSize: parseSize(uniqueStr), Containers: containers}
195		}
196	
197		return lookup
198	}
