6	)
7	
8	// safeSlice returns s[start:end] clamped to valid bounds
9	func safeSlice(s string, start, end int) string {
10		if start < 0 {
11			start = 0
12		}
13		if start >= len(s) {
14			return ""
15		}
16		if end > len(s) {
17			end = len(s)
18		}
19		return s[start:end]
20	}
21	
22	// parseNetIO parses Docker NetIO string "1.2kB / 3.4kB" into received and transmitted bytes
23	func parseNetIO(netIO string) (rx, tx int64) {
24		return parsePair(netIO)
25	}
26	
27	// parsePair splits one of Docker's "used / total" cells into its two sides.
28	//
29	// It is named apart from parseNetIO because it serves MemUsage too, where the
30	// halves are "used" and "limit" rather than received and sent — the parsing is
31	// identical, the words are not, and a memory reading going through a function
32	// called parseNetIO would read as a mistake at every call site.
33	func parsePair(cell string) (left, right int64) {
